mapper.select:
/* AdminAccountMapper.findById */
SELECT id, email, password, nickname, role, status, must_change_password, last_login_at, created_at, updated_at
FROM admin_account
WHERE id = #{id}

mapper.update:
/* AdminAccountMapper.updateLastLoginAt */
UPDATE admin_account
SET last_login_at = NOW(), updated_at = NOW()
WHERE id = #{id}

/* AdminAccountMapper.updatePassword */
UPDATE admin_account
SET password = #{password}, updated_at = NOW()
WHERE id = #{id}

mapper.select:
/* AdminAccountMapper.selectAccounts */
SELECT id, email, password, nickname, role, status, must_change_password, last_login_at, created_at, updated_at
FROM admin_account

ORDER BY id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.insert:
/* AdminAccountMapper.insert */
INSERT INTO admin_account (email, password, nickname, role, status, must_change_password, created_at, updated_at)
VALUES (#{email}, #{password}, #{nickname}, #{role}, #{status}, #{mustChangePassword}, NOW(), NOW())

mapper.update:
/* AdminAccountMapper.updatePasswordAndFlag */
UPDATE admin_account
SET password = #{password}, must_change_password = #{mustChangePassword}, updated_at = NOW()
WHERE id = #{id}
